import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private Connection dbConn;

    @Override
    public void init() throws ServletException {
        try {
            String dbUrl = System.getenv("DB_JDBC_URL");
            String dbUser = System.getenv("DB_USER");
            String dbPass = System.getenv("DB_PASS");
            dbConn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
            log.info("Database connection established");
        } catch (SQLException e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("^(summary|detail|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date format validation
        if (!startDate.matches("^\\d{4}-\\d{2}-\\d{2}$") ||
            !endDate.matches("^\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        try {
            String query = buildQuery(reportType, startDate, endDate, department);
            log.fine("Executing report query for type: " + reportType);
            Statement stmt = dbConn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
            rs.close();
            stmt.close();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportType, String startDate, String endDate, String department) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(reportType);
        sb.append(" WHERE created_at >= '").append(startDate).append("'");
        sb.append(" AND created_at <= '").append(endDate).append("'");

        // Department filter - user controlled, concatenated directly
        if (department != null && !department.isEmpty()) {
            sb.append(" AND department = '").append(department).append("'");
        }

        sb.append(" ORDER BY created_at DESC LIMIT 1000");
        return sb.toString();
    }

    @Override
    public void destroy() {
        try {
            if (dbConn != null && !dbConn.isClosed()) {
                dbConn.close();
            }
        } catch (SQLException e) {
            log.warning("Error closing DB connection");
        }
    }
}
